/* Getting started, Dashboard, Inbox, Employees, Workforce */
G('start', ['Getting started', 'शुरुआत'], ['The basics that every person using Mirror-HR should know.', 'Mirror-HR इस्तेमाल करने वाले हर व्यक्ति को ये बुनियादी बातें पता होनी चाहिए।'], [
  { id: 'login', n: ['Sign in and sign out', 'लॉग-इन और लॉग-आउट'],
    path: ['Login page', 'लॉग-इन पेज'],
    what: ['The first screen. You enter your company code, your employee number (for example E004) and your password.', 'पहली स्क्रीन। यहाँ कंपनी कोड, आपका एम्प्लॉई नंबर (जैसे E004) और पासवर्ड डालते हैं।'],
    why: ['So that every person sees only what belongs to them and to their role.', 'ताकि हर व्यक्ति को सिर्फ़ वही दिखे जो उसका और उसकी भूमिका का है।'],
    who: ['Everyone.', 'सब।'],
    steps: [['Open the Mirror-HR link in your browser.', 'ब्राउज़र में Mirror-HR का लिंक खोलें।'], ['Type the company code, your employee number and your password, then press Sign in.', 'कंपनी कोड, एम्प्लॉई नंबर और पासवर्ड डालकर Sign in दबाएँ।'], ['If you forgot the password, press Forgot password and follow the steps.', 'पासवर्ड भूल गए हों तो Forgot password दबाएँ और बताए स्टेप चलें।'], ['To sign out, press the arrow icon at the top right, next to your name.', 'लॉग-आउट के लिए ऊपर दाएँ आपके नाम के पास वाला तीर का आइकन दबाएँ।']],
    notes: [['Your changes are saved to the database a moment after you make them. Signing out first saves anything still waiting, and the browser warns you if you close the page before it is saved. Signing out on one device does not close the same login on your other devices. If the strip on top of the page shows a ⚠ sign with a message, or a message says Not saved to the database, the change was NOT saved: note the message and tell Mirror-HR. If a part of the first screen cannot be drawn, you stay signed in and the top strip says so; your changes are still saved.', 'आपके बदलाव करने के थोड़ी देर बाद डेटाबेस में सेव हो जाते हैं। Sign out करने पर जो बाक़ी है वह पहले सेव हो जाता है, और सेव होने से पहले पेज बंद करें तो ब्राउज़र चेतावनी देता है। एक डिवाइस पर Sign out करने से आपके दूसरे डिवाइस का वही लॉगिन बंद नहीं होता। पेज के ऊपर की पट्टी में ⚠ के साथ संदेश दिखे, या संदेश आए कि Not saved to the database, तो बदलाव सेव नहीं हुआ: संदेश नोट करें और Mirror-HR को बताएँ। पहली स्क्रीन का कोई हिस्सा न बन पाए तो आप साइन-इन रहते हैं और ऊपर की पट्टी में लिखा आता है; आपके बदलाव फिर भी सेव होते हैं।'], ['After too many wrong passwords the account is locked for a short time. HR can unlock it.', 'कई बार गलत पासवर्ड डालने पर अकाउंट थोड़ी देर के लिए लॉक हो जाता है। HR उसे खोल सकता है।']] },
  { id: 'setup', n: ['Set up a new company: step by step', 'नई कंपनी का सेटअप: स्टेप बाय स्टेप'],
    path: ['Setup guide (left menu) and the card on the Dashboard', 'Setup guide (बाएँ मेनू में) और Dashboard का कार्ड'],
    what: ['The order in which a new company sets up Mirror-HR, and why that order: each step depends on the ones before it. The Setup guide page and the card on the Dashboard show the same steps with a tick for each one that is done. A tick comes from your real data (for example the employees you added); the steps that cannot be read from data you mark yourself with Mark as done, after you have looked at them. A step is locked while something it needs is not done.', 'नई कंपनी Mirror-HR को किस क्रम में सेट करती है, और वही क्रम क्यों: हर स्टेप पिछले स्टेप पर टिका है। Setup guide पेज और Dashboard का कार्ड वही स्टेप दिखाते हैं, पूरे हुए स्टेप पर टिक के साथ। टिक आपके असली डेटा से आता है (जैसे आपने जोड़े हुए कर्मचारी); जो स्टेप डेटा से पढ़े नहीं जा सकते उन्हें देखने के बाद आप ख़ुद Mark as done से पूरा करें। जिस चीज़ पर स्टेप टिका है वह पूरी न हो तो स्टेप लॉक रहता है।'],
    why: ['So that nothing is set up too early or too late. For example, salary needs the designations, and an employee cannot be added without the organization chain.', 'ताकि कुछ भी बहुत जल्दी या बहुत देर से सेट न हो। जैसे सैलरी को पद चाहिए, और ऑर्गनाइज़ेशन की चेन के बिना कर्मचारी नहीं जुड़ सकता।'],
    who: ['Admin and HR. Anyone who is given the right Setup guide in Core Setting > Rights.', 'Admin और HR। जिसे भी Core Setting > Rights में Setup guide का अधिकार दिया जाए।'],
    steps: [
      ['1. Company basics. Core Setting > General: name, address, state, notice period. Core Setting > Code series: the format of the employee code. Set the format before you add employees: codes already given do not change.', '1. कंपनी की बुनियादी जानकारी। Core Setting > General: नाम, पता, राज्य, नोटिस अवधि। Core Setting > Code series: कर्मचारी कोड का फ़ॉर्मेट। कर्मचारी जोड़ने से पहले फ़ॉर्मेट तय करें: दिए गए कोड बदलते नहीं।'],
      ['2. Organization. Core Setting, in this order: Functions, Departments, Branches, Divisions, Sub-divisions, Designations. Check the Career levels. Then write and publish the JD & JS of each designation.', '2. ऑर्गनाइज़ेशन। Core Setting में इसी क्रम में: Functions, Departments, Branches, Divisions, Sub-divisions, Designations। Career levels जाँचें। फिर हर पद की JD और JS लिखकर Publish करें।'],
      ['3. Salary and statutory. Payroll > Salary structure for every designation and level (it needs the designations and the levels). Payroll > Statutory rules: confirm the PF, ESIC, PT, TDS and LWF values with your CA.', '3. सैलरी और statutory। Payroll > Salary structure हर पद और लेवल के लिए (इसे पद और लेवल चाहिए)। Payroll > Statutory rules: PF, ESIC, PT, TDS और LWF की वैल्यू अपने CA से पक्की करें।'],
      ['4. Time office and leave. Core Setting > Shifts (with the attendance rules), Holidays, and the Leave types, quota and rules.', '4. टाइम ऑफ़िस और छुट्टी। Core Setting > Shifts (हाज़िरी के नियमों के साथ), Holidays, और Leave types, quota और rules।'],
      ['5. Who sees what. Core Setting > Rights: check what Admin, HR, Manager and Employee see, before you give logins.', '5. कौन क्या देखे। Core Setting > Rights: लॉगिन देने से पहले जाँचें कि Admin, HR, Manager और Employee क्या देखते हैं।'],
      ['6. Employees. Add Admin and HR first, then the managers, then the rest, with + Add employee or the bulk upload (use the codes from Download master codes). Add a manager before his team: a person gets the Manager login only if people already report to him.', '6. कर्मचारी। पहले Admin और HR, फिर मैनेजर, फिर बाक़ी जोड़ें, + Add employee या बल्क अपलोड से (Download master codes के कोड इस्तेमाल करें)। मैनेजर को उसकी टीम से पहले जोड़ें: Manager लॉगिन तभी मिलता है जब लोग पहले से उसे रिपोर्ट करते हों।'],
      ['6a. Company policies. Policy Management: upload each policy as a clean Word or text file (not an old-font PDF) and publish it; the HR Assistant answers only from these, so without them it cannot answer. Then ask it the real questions in Test Chat and mark the step done. Then, in the Knowledge library, publish every mandatory policy with “acknowledgement needed”: every employee must acknowledge it, and the Acknowledgements tab shows who has not. The step is checked from the acknowledgements of your employees.', '6a. कंपनी की पॉलिसी। Policy Management में हर पॉलिसी साफ़ Word या टेक्स्ट फ़ाइल के रूप में अपलोड करें (पुराने फ़ॉन्ट वाली PDF नहीं) और प्रकाशित करें; HR Assistant सिर्फ़ इन्हीं से जवाब देता है, इसलिए इनके बिना वह जवाब नहीं दे सकता। फिर Test Chat में असली सवाल पूछकर स्टेप को पूरा मार्क करें। फिर Knowledge library में हर ज़रूरी पॉलिसी “पावती ज़रूरी” के साथ प्रकाशित करें: हर कर्मचारी को पावती देनी होती है, और Acknowledgements टैब में दिखता है किसने नहीं दी। यह स्टेप कर्मचारियों की पावती से जाँचा जाता है।'],
      ['7. What follows the employees. Give every employee a reporting manager (and a functional manager if any). Give the logins: the user id is the employee number, the first password is shown once, so hand it over with the company code; set the HR and Manager roles in Core Setting > Accounts. Map the approval roles in Core Setting > Roles to real people (the ready roles point to sample people), then check the approval paths in Core Setting > Workflow. Then, for every employee, in Workforce > Onboarding: the shift, the statutory assignment (PF, ESIC, PT, TDS, LWF), the salary structure reaching him, the KYC documents, the KPIs (the KPI pack is built by Mirror-HR) and the appointment letter.', '7. कर्मचारियों के बाद के काम। हर कर्मचारी को रिपोर्टिंग मैनेजर दें (और हो तो फ़ंक्शनल मैनेजर)। लॉगिन दें: यूज़र आईडी कर्मचारी नंबर है, पहला पासवर्ड एक बार दिखता है, इसलिए कंपनी कोड के साथ उसे सौंपें; Core Setting > Accounts में HR और Manager रोल तय करें। Core Setting > Roles के अप्रूवल रोल असली लोगों से जोड़ें (तैयार रोल नमूने के लोगों की तरफ़ इशारा करते हैं), फिर Core Setting > Workflow में अप्रूवल के रास्ते जाँचें। फिर हर कर्मचारी के लिए Workforce > Onboarding में: शिफ़्ट, statutory असाइनमेंट (PF, ESIC, PT, TDS, LWF), सैलरी स्ट्रक्चर का उस तक पहुँचना, KYC दस्तावेज़, KPI (KPI पैक Mirror-HR बनाता है) और नियुक्ति पत्र।'],
      ['8. First month. Get the attendance (machine, import or by hand), process the attendance of the month in Time Office, generate the variable pay (if Performance is on), then run payroll and approve it. ', '8. पहला महीना। हाज़िरी लें (मशीन, इम्पोर्ट या हाथ से), Time Office में महीने की हाज़िरी प्रोसेस करें, वेरिएबल पे बनाएँ (अगर Performance चालू है), फिर पेरोल रन करें और मंज़ूर करें। '],
      ['9. Hiring, when you need it. Manpower plan, then Requisition, then Vacancy (it needs the JD & JS), candidates, the Offer (it needs the salary structure of the designation and level) and Mark joined (it needs the verified documents).', '9. भर्ती, जब ज़रूरत हो। मैनपावर प्लान, फिर माँग (Requisition), फिर वैकेंसी (इसे JD और JS चाहिए), उम्मीदवार, ऑफ़र (इसे पद और लेवल का सैलरी स्ट्रक्चर चाहिए) और Mark joined (इसे सत्यापित दस्तावेज़ चाहिए)।'],
      ['10. Module setups and the Pending tab. The Setup guide page has three tabs: Core order (the steps above, in order), Module setups, and Pending: where is what left. Module setups run beside the core order and do not stop it. For each module that is switched on for your company (Training, CRM, Performance, Recruitment, Exit, Support desk, Assets, Stock audit, Knowledge library) it lists what must be set up, for example the OJT templates, the question bank and the self-training videos for Training, or the feedback form for CRM, and what stays incomplete without it. A step is ticked from your real data, or you mark it yourself. The three cards on top show the core steps done, the module setups done and how many modules still have setups pending. The Pending tab groups what is left by module, marks each module Not started or Half done, and says how to upgrade it. The Dashboard card also says how many modules have setups pending.', '10. मॉड्यूल सेटअप और Pending टैब। Setup guide पेज पर तीन टैब हैं: Core order (ऊपर के स्टेप, क्रम में), Module setups, और Pending: कहाँ क्या बाक़ी है। Module setups मुख्य क्रम के साथ-साथ चलते हैं और उसे रोकते नहीं। आपकी कंपनी के लिए चालू हर मॉड्यूल (Training, CRM, Performance, Recruitment, Exit, Support desk, Assets, Stock audit, Knowledge library) के लिए यह बताता है कि क्या सेट करना है, जैसे Training के OJT टेम्पलेट, सवालों का बैंक और सेल्फ़-ट्रेनिंग के वीडियो, या CRM का फ़ीडबैक फ़ॉर्म, और उसके बिना क्या अधूरा रहता है। स्टेप आपके असली डेटा से टिक होता है, या आप ख़ुद मार्क करते हैं। ऊपर के तीन कार्ड बताते हैं कितने मुख्य स्टेप पूरे हुए, कितने मॉड्यूल सेटअप पूरे हुए और कितने मॉड्यूल के सेटअप अभी बाक़ी हैं। Pending टैब बाक़ी काम को मॉड्यूल के हिसाब से इकट्ठा करता है, हर मॉड्यूल को Not started या Half done बताता है, और उसे पूरा करने का रास्ता दिखाता है। Dashboard का कार्ड भी बताता है कितने मॉड्यूल के सेटअप बाक़ी हैं।']],
    notes: [['What depends on what: an employee needs the organization chain and the code format. The offer letter, the CTC, the payslip and payroll need the salary structure. A vacancy needs a manpower plan row and the JD & JS. Leave and other approvals need the reporting manager, and the approval roles need real people. Payroll needs the attendance of the month processed, the salary structure, the statutory assignment and, if Performance is on, the variable pay.', 'कौन किस पर टिका है: कर्मचारी को ऑर्गनाइज़ेशन की चेन और कोड फ़ॉर्मेट चाहिए। ऑफ़र लेटर, CTC, पे-स्लिप और पेरोल को सैलरी स्ट्रक्चर चाहिए। वैकेंसी को मैनपावर प्लान की पंक्ति और JD और JS चाहिए। छुट्टी और बाक़ी मंज़ूरियों को रिपोर्टिंग मैनेजर चाहिए, और अप्रूवल रोल को असली लोग। पेरोल को महीने की प्रोसेस हुई हाज़िरी, सैलरी स्ट्रक्चर, statutory असाइनमेंट और (Performance चालू हो तो) वेरिएबल पे चाहिए।']] },
  { id: 'topbar', n: ['The top bar: language, guide, bell, your name', 'ऊपर की पट्टी: भाषा, गाइड, घंटी, आपका नाम'],
    path: ['Top right of every screen', 'हर स्क्रीन का ऊपर दायाँ हिस्सा'],
    what: ['EN / हिं switches the language of the whole app. The book icon opens this User Guide. The bell shows your latest notifications. The key icon changes your password.', 'EN / हिं पूरे ऐप की भाषा बदलता है। किताब का आइकन यह यूज़र गाइड खोलता है। घंटी आपकी ताज़ा सूचनाएँ दिखाती है। चाबी का आइकन पासवर्ड बदलता है।'],
    why: ['So that help, alerts and settings are one click away from any screen.', 'ताकि मदद, अलर्ट और सेटिंग हर स्क्रीन से एक क्लिक पर रहें।'],
    who: ['Everyone.', 'सब।'],
    steps: [['Press EN or हिं to change the language.', 'भाषा बदलने के लिए EN या हिं दबाएँ।'], ['Press the book icon to read the guide. Type a word in the search box to find a topic.', 'गाइड पढ़ने के लिए किताब का आइकन दबाएँ। विषय खोजने के लिए सर्च बॉक्स में शब्द लिखें।'], ['Press the bell to see what is new. Your full list of work is in the Inbox.', 'नया क्या है देखने के लिए घंटी दबाएँ। आपके काम की पूरी लिस्ट Inbox में है।']] },
  { id: 'sidebar', n: ['The left menu (modules)', 'बायाँ मेन्यू (मॉड्यूल)'],
    path: ['Left side of every screen', 'हर स्क्रीन का बायाँ हिस्सा'],
    what: ['Each bar on the left is a module. Press a module name to open it and see its sections. You see only the modules your company has taken and your role may open.', 'बाईं तरफ़ की हर पट्टी एक मॉड्यूल है। मॉड्यूल का नाम दबाने पर वह खुलता है और उसके सेक्शन दिखते हैं। आपको सिर्फ़ वही मॉड्यूल दिखते हैं जो आपकी कंपनी ने लिए हैं और जिन्हें आपकी भूमिका खोल सकती है।'],
    why: ['To keep the work of the company in one place, grouped the way people think about it.', 'ताकि कंपनी का सारा काम एक जगह रहे और उसी तरह बँटा हो जैसे लोग सोचते हैं।'],
    who: ['Everyone.', 'सब।'],
    steps: [['On a computer, move the mouse over a module name, for example Payroll. Its sections open in a panel to the right of the menu.', 'कंप्यूटर पर किसी मॉड्यूल के नाम पर माउस ले जाएँ, जैसे Payroll। उसके सेक्शन मेन्यू के दाईं ओर एक पैनल में खुलते हैं।'], ['Press a section in the panel to open that screen. The panel closes by itself. Press Esc or move the mouse away to close it without choosing.', 'उस स्क्रीन को खोलने के लिए पैनल का सेक्शन दबाएँ। पैनल अपने-आप बंद हो जाता है। बिना चुने बंद करने के लिए Esc दबाएँ या माउस हटा लें।'], ['Pressing the module name itself opens its first section. The module you are in is highlighted.', 'मॉड्यूल का नाम दबाने पर उसका पहला सेक्शन खुलता है। आप जिस मॉड्यूल में हैं वह हाइलाइट रहता है।'], ['On a phone or a small screen, press the three-line button at the top left to open the menu. There a module opens downward when you press it.', 'फ़ोन या छोटी स्क्रीन पर मेन्यू खोलने के लिए ऊपर बाएँ तीन लाइनों वाला बटन दबाएँ। वहाँ मॉड्यूल दबाने पर वह नीचे की ओर खुलता है।']] },
  { id: 'roles', n: ['Who can see and do what (roles)', 'कौन क्या देख और कर सकता है (भूमिकाएँ)'],
    path: ['Core Setting > Automation > Rights', 'Core Setting > Automation > Rights'],
    what: ['There are four roles: Employee, Manager, HR and Admin. A manager sees his own team. HR and Admin set up the company. Admin always has full access.', 'चार भूमिकाएँ हैं: Employee, Manager, HR और Admin। मैनेजर अपनी टीम देखता है। HR और Admin कंपनी का सेट-अप करते हैं। Admin के पास हमेशा पूरा एक्सेस रहता है।'],
    why: ['So that salary, personal details and approvals reach only the right people.', 'ताकि सैलरी, निजी जानकारी और मंज़ूरियाँ सिर्फ़ सही लोगों तक पहुँचें।'],
    who: ['HR and Admin set it. Everyone is affected by it.', 'HR और Admin तय करते हैं। असर सब पर पड़ता है।'], hr: true,
    steps: [['Open Core Setting > Automation > Rights.', 'Core Setting > Automation > Rights खोलें।'], ['Choose a role at the top.', 'ऊपर से एक भूमिका चुनें।'], ['Tick or untick View, Add, Edit, Approve and Export for each page.', 'हर पेज के लिए View, Add, Edit, Approve और Export पर टिक लगाएँ या हटाएँ।']] }
]);

G('dashboard', ['Dashboard', 'डैशबोर्ड'], ['Your home screen: how you are doing, your target, what is waiting today, and what you earned.', 'आपकी होम स्क्रीन: आप कैसा कर रहे हैं, आपका टारगेट, आज क्या बाकी है और आपने क्या कमाया।'], [
  { id: 'att', n: ['Company today and Team today', 'कंपनी आज और टीम आज'],
    path: ['Dashboard > Company today (Admin, HR) or Team today (reporting manager)', 'Dashboard > Company today (Admin, HR) या Team today (रिपोर्टिंग मैनेजर)'], hr: true,
    what: ['Filters for Function, Department, Branch, Division, Sub-division and Designation. Under them five boxes for one day: Total employees, Present, Absent, On leave and Weekly off / holiday, each with its percentage of the total. Below is a bar chart of the present percentage of each day.', 'Function, Department, Branch, Division, Sub-division और Designation के फ़िल्टर। उनके नीचे एक दिन के पाँच बॉक्स: Total employees, Present, Absent, On leave और Weekly off / holiday, हर एक कुल के प्रतिशत के साथ। नीचे हर दिन के present प्रतिशत का बार चार्ट।'],
    why: ['So that the Admin can see in one look how any part of the company is attending, today and on the days before, without opening a report.', 'ताकि Admin कंपनी के किसी भी हिस्से की हाज़िरी आज और पिछले दिनों की एक नज़र में देख सके, रिपोर्ट खोले बिना।'],
    who: ['Admin and HR see the whole company. A reporting manager sees everybody who reports to them, directly or through others.', 'Admin और HR पूरी कंपनी देखते हैं। रिपोर्टिंग मैनेजर उन सबको देखता है जो उसे सीधे या दूसरों के ज़रिए रिपोर्ट करते हैं।'],
    steps: [['Open Dashboard. The first tab is Company today (Team today for a manager).', 'Dashboard खोलें। पहला टैब Company today है (मैनेजर के लिए Team today)।'], ['Choose one or more filters from the pills at the top. A pill turns green when it has a value, and Reset clears them all. For example Branch = Surat Store and Division = Sarees. The boxes and the chart change at once.', 'ऊपर की गोलियों (pill) से एक या ज़्यादा फ़िल्टर चुनें। मान चुनने पर pill हरी हो जाती है, और Reset सबको साफ़ करता है। जैसे Branch = Surat Store और Division = Sarees। बॉक्स और चार्ट तुरंत बदल जाते हैं।'], ['The boxes show today. Press a bar of the chart to see that day in the boxes.', 'बॉक्स आज का दिन दिखाते हैं। किसी दिन को बॉक्स में देखने के लिए चार्ट की बार दबाएँ।'], ['Choose the period at the top right of the chart: the last 14 days, or a month.', 'चार्ट के ऊपर दाईं ओर से अवधि चुनें: पिछले 14 दिन, या कोई महीना।']],
    notes: [['The percentage in the boxes is of the total employees. The percentage in the bars is of the people who had to work: weekly off, holidays and people without a shift are left out.', 'बॉक्स का प्रतिशत कुल कर्मचारियों का है। बार का प्रतिशत उन लोगों का है जिन्हें काम करना था: साप्ताहिक अवकाश, छुट्टी और बिना शिफ़्ट वाले छोड़े गए हैं।'], ['For today, the Absent box is called “Not punched in yet”, because the day is not over.', 'आज के लिए Absent बॉक्स का नाम “Not punched in yet” है, क्योंकि दिन पूरा नहीं हुआ।'], ['An employee who has no shift on that day is in the total but not in present or absent. A yellow note tells how many. Give them a shift in Time Office > Shift assignment.', 'जिस कर्मचारी की उस दिन कोई शिफ़्ट नहीं वह कुल में है पर present या absent में नहीं। पीले नोट में गिनती दिखती है। उन्हें Time Office > Shift assignment में शिफ़्ट दें।']] },
  { id: 'perf', n: ['My Performance', 'मेरा परफ़ॉर्मेंस'],
    path: ['Dashboard > My Performance', 'Dashboard > My Performance'],
    what: ['Your KPI score of the last months, your career level, your monthly pay potential and the KPIs you are strong or weak in.', 'पिछले महीनों का आपका KPI स्कोर, करियर लेवल, मासिक कमाई की संभावना और वे KPI जिनमें आप मज़बूत या कमज़ोर हैं।'],
    why: ['So that you know every month how you are doing and what to improve, without asking anyone.', 'ताकि आपको हर महीने बिना किसी से पूछे पता रहे कि आप कैसा कर रहे हैं और क्या सुधारना है।'],
    who: ['Every employee, including Admin, HR and managers (their own KPIs; the company or team attendance is in the first tab).', 'हर कर्मचारी, Admin, HR और मैनेजर भी (अपने KPI; कंपनी या टीम की हाज़िरी पहले टैब में है)।'],
    steps: [['Open Dashboard. My Performance is the first tab (the second tab for Admin, HR and managers, after Company today or Team today).', 'Dashboard खोलें। My Performance पहला टैब है (Admin, HR और मैनेजर के लिए Company today या Team today के बाद दूसरा)।'], ['Read the four boxes on top: latest KPI score, previous month, quarter average and performance band.', 'ऊपर के चार बॉक्स पढ़ें: ताज़ा KPI स्कोर, पिछला महीना, तिमाही का औसत और परफ़ॉर्मेंस बैंड।'], ['Read Top 3 strong KPIs and Top 3 to improve.', 'Top 3 strong KPIs और Top 3 to improve पढ़ें।']],
    notes: [['Your first score appears only after your first month is closed.', 'आपका पहला स्कोर पहला महीना बंद होने के बाद ही आता है।']] },
  { id: 'tgt', n: ['My Target', 'मेरा टारगेट'],
    path: ['Dashboard > My Target', 'Dashboard > My Target'],
    what: ['Your sales or work target for this month, how much is achieved, and how much you need each day to reach it.', 'इस महीने का आपका सेल्स या काम का टारगेट, कितना हो गया, और उसे पाने के लिए रोज़ कितना चाहिए।'],
    why: ['So that you can plan the month day by day instead of finding out at the end.', 'ताकि आप महीने को रोज़ के हिसाब से चला सकें, अंत में पता न चले।'],
    who: ['Employees who have a target.', 'जिन कर्मचारियों का टारगेट है।'],
    steps: [['Open Dashboard > My Target.', 'Dashboard > My Target खोलें।'], ['See the target, the achieved amount and the percentage.', 'टारगेट, हुई रकम और प्रतिशत देखें।'], ['Read “needed today” to know how much to do today to stay on pace.', '“आज चाहिए” पढ़ें ताकि पता रहे कि रफ़्तार बनाए रखने के लिए आज कितना करना है।']] },
  { id: 'today', n: ['Today and requests', 'आज और माँगें'],
    path: ['Dashboard > Today and requests', 'Dashboard > Today and requests'],
    what: ['What happens today: your attendance, leave balance, requests waiting for approval and quick actions.', 'आज क्या है: आपकी हाज़िरी, छुट्टी का बैलेंस, मंज़ूरी के इंतज़ार में माँगें और जल्दी के काम।'],
    why: ['So that the daily things are done from one place.', 'ताकि रोज़ के काम एक ही जगह से हो जाएँ।'],
    who: ['Everyone. A manager also sees the requests of the team.', 'सब। मैनेजर को टीम की माँगें भी दिखती हैं।'],
    steps: [['Open Dashboard > Today and requests.', 'Dashboard > Today and requests खोलें।'], ['Check in or out, apply for leave or follow your requests from the boxes shown.', 'दिखाए गए बॉक्स से चेक-इन या चेक-आउट करें, छुट्टी माँगें या अपनी माँगें देखें।']] },
  { id: 'earned', n: ['Salary Earned', 'अर्जित सैलरी'],
    path: ['Dashboard > Salary Earned', 'Dashboard > Salary Earned'],
    what: ['Shows what your salary structure promised, what you actually earned, and exactly where you lost money: which KPI scored low, and how many days of absence.', 'दिखाता है कि आपके सैलरी स्ट्रक्चर में कितना था, आपने असल में कितना कमाया, और पैसा ठीक कहाँ गया: कौन-सा KPI कम रहा और कितने दिन अनुपस्थिति रही।'],
    why: ['So that you understand your salary and know what to improve to earn the full amount.', 'ताकि आप अपनी सैलरी समझें और जानें कि पूरी रकम पाने के लिए क्या सुधारना है।'],
    who: ['Every employee, for his own salary.', 'हर कर्मचारी, अपनी सैलरी के लिए।'],
    steps: [['Open Dashboard > Salary Earned. The tab appears once your payroll exists.', 'Dashboard > Salary Earned खोलें। यह टैब तब दिखता है जब आपकी पेरोल बन चुकी हो।'], ['Pick a month at the top.', 'ऊपर से महीना चुनें।'], ['Read the four boxes: could have earned, actually earned, difference, net pay.', 'चार बॉक्स पढ़ें: कमा सकते थे, असल में कमाया, अंतर, हाथ में।'], ['Read “Where the difference came from” and the table “Which KPI cost you money”.', '“अंतर कहाँ से आया” और “किस KPI से पैसे गए” वाली टेबल पढ़ें।']],
    notes: [['When the month is not closed yet, the variable pay shows as pending. Nothing is lost until the KPI score is known.', 'महीना बंद न हुआ हो तो वेरिएबल पे “बाकी” दिखता है। KPI स्कोर आने तक कुछ नहीं गिना जाता।'], ['When your salary is paid, you get a notice in the Inbox with a link to this tab.', 'सैलरी मिलने पर Inbox में एक सूचना आती है जिसमें इसी टैब का लिंक होता है।']] }
]);

G('inbox', ['Inbox', 'इनबॉक्स'], ['Everything that is waiting for you, from every module, in one list.', 'हर मॉड्यूल का वह सब जो आपका इंतज़ार कर रहा है, एक ही लिस्ट में।'], [
  { id: 'gameview', n: ['Game view (home map)', 'गेम व्यू (होम मैप)'],
    path: ['Top bar > game button (next to the User Guide button)', 'ऊपर की पट्टी > गेम बटन (यूज़र गाइड बटन के पास)'],
    what: ['A second look for the home page. The modules are shown as tiles on a map, each with one line that says what it is for and a red number of the items waiting there. Your Inbox shows as “Today\'s missions”. Nothing else changes: the pages, the data and the rights are the same.', 'होम पेज का दूसरा रूप। मॉड्यूल मैप पर टाइल की तरह दिखते हैं, हर एक के नीचे एक लाइन में लिखा है कि वह किस काम का है और लाल नंबर बताता है कि वहाँ कितने आइटम बाकी हैं। आपका इनबॉक्स “आज के मिशन” के रूप में दिखता है। बाकी कुछ नहीं बदलता: पेज, डेटा और अधिकार वही हैं।'],
    why: ['So that a new person can see at once which module does what, and what must be done today.', 'ताकि नया व्यक्ति तुरंत देख सके कि कौन सा मॉड्यूल किस काम का है और आज क्या करना है।'],
    who: ['Everyone. Each person chooses Game view or Classic view for himself; the choice is saved with his login, so it is the same on every phone and computer.', 'सब। हर व्यक्ति अपने लिए गेम व्यू या क्लासिक व्यू चुनता है; यह पसंद उसके लॉगिन के साथ सेव होती है, इसलिए हर फ़ोन और कंप्यूटर पर वही रहती है।'],
    steps: [['Press the game button in the top bar. The home page becomes the map.', 'ऊपर की पट्टी में गेम बटन दबाएँ। होम पेज मैप बन जाता है।'], ['Press a tile to open that module. Press “Map” on top of the page to come back.', 'मॉड्यूल खोलने के लिए टाइल दबाएँ। वापस आने के लिए पेज के ऊपर “मैप” दबाएँ।'], ['Press a mission to open the work. The label shows the last date: today, tomorrow or overdue.', 'काम खोलने के लिए मिशन दबाएँ। लेबल आख़िरी तारीख़ दिखाता है: आज, कल या समय निकल गया।'], ['Choose one of the two colours with the round buttons: Teal Night + Gold or Sky Day + Coral.', 'गोल बटन से दो में से एक रंग चुनें: Teal Night + Gold या Sky Day + Coral।'], ['Press “Classic view”, or the game button again, to go back to the usual Dashboard.', 'पुराने डैशबोर्ड पर लौटने के लिए “क्लासिक व्यू” या फिर से गेम बटन दबाएँ।']],
    notes: [['The top strip shows your career level, your KPI score of the month so far (only the KPIs already scored), the days in a row you came on time this month, and the missions waiting.', 'ऊपर की पट्टी में आपका करियर लेवल, इस महीने का अब तक का KPI स्कोर (सिर्फ़ वे KPI जिनका स्कोर बन चुका है), इस महीने लगातार समय पर आने के दिन और बाकी मिशन दिखते हैं।'], ['The ranking lists everyone of your division with the KPI score so far. A person with no division sees the whole company.', 'रैंकिंग में आपके डिवीज़न के सभी लोग अब तक के KPI स्कोर के साथ दिखते हैं। जिसका डिवीज़न नहीं है उसे पूरी कंपनी दिखती है।'], ['The bar at the bottom opens the most used work in one press: punch, leave, payslip, ticket, Inbox and the HR Assistant.', 'नीचे की पट्टी से सबसे ज़्यादा होने वाले काम एक बार दबाने से खुलते हैं: पंच, छुट्टी, पे-स्लिप, टिकट, इनबॉक्स और HR Assistant।'],
      ['In Game view the Leave page starts with a guide block. “Where is your leave now?” shows your request as a path: You applied, Approval (with the name of the person it is waiting with), Leave granted or Rejected. It shows your oldest waiting request; if none is waiting, your latest leave of the last 7 days; if there is none, how a leave moves. Under it is one card for every section you may open (Apply for leave, My balance and history, Approve team leave, Short leave, Encash leave, Holidays) with one line on what it is for, and a “Good to know” line. The usual Leave page is below, unchanged.', 'गेम व्यू में Leave पेज एक गाइड ब्लॉक से शुरू होता है। “आपकी छुट्टी अभी कहाँ है?” आपकी माँग को रास्ते की तरह दिखाता है: आपने माँग भेजी, मंज़ूरी (जिसके पास बाकी है उसका नाम), छुट्टी मिली या अस्वीकृत। यह आपकी सबसे पुरानी बाकी माँग दिखाता है; कोई बाकी न हो तो पिछले 7 दिन की ताज़ा छुट्टी; वह भी न हो तो छुट्टी कैसे आगे बढ़ती है। उसके नीचे हर उस हिस्से का एक कार्ड है जिसे आप खोल सकते हैं (छुट्टी लगाएँ, मेरा बैलेंस और इतिहास, टीम की छुट्टी मंज़ूर करें, शॉर्ट लीव, नक़दीकरण, छुट्टियों की सूची), एक लाइन में उसका काम, और “जानने लायक” की एक लाइन। उसके नीचे पुराना Leave पेज वैसा ही है।'],
      ['Every other module page has the same kind of guide block in Game view: the name of the module with one line on what it is for, “How the work moves here” as a path of 3 to 5 steps, and a card for every section of the page that you may open, with its line from this User Guide. The card of the section you are on says “You are here”. When a page has more than 8 sections, “Show all sections” opens the rest. On Attendance requests, Location requests, Payroll (salary advance), Expense, My Asset and Exits the path shows your own waiting request and who it is with. “Hide guide” folds the block of that page; “Show guide” brings it back.', 'गेम व्यू में बाकी हर मॉड्यूल पेज पर भी ऐसा ही गाइड ब्लॉक है: मॉड्यूल का नाम और एक लाइन कि वह किस काम का है, “यहाँ काम कैसे चलता है” 3 से 5 क़दम के रास्ते के रूप में, और पेज के हर उस हिस्से का एक कार्ड जिसे आप खोल सकते हैं, इसी यूज़र गाइड की लाइन के साथ। जिस हिस्से पर आप हैं उसके कार्ड पर “आप यहीं हैं” लिखा होता है। जिस पेज में 8 से ज़्यादा हिस्से हैं वहाँ “सभी हिस्से दिखाएँ” बाकी खोलता है। Attendance requests, Location requests, Payroll (सैलरी एडवांस), Expense, My Asset और Exits पर रास्ता आपकी अपनी बाकी माँग और वह किसके पास है, यह दिखाता है। “गाइड छिपाएँ” उस पेज का ब्लॉक समेट देता है; “गाइड दिखाएँ” वापस लाता है।'],
      ['Badges of the month are on the map, under the ranking, and counted in the top strip. There are seven, all worked out from your real records of the running month: On time (no late day, at least 5 days present), Full attendance (no absent day, at least 5 days present), 7-day streak (7 working days in a row on time), Inbox hero (at least 3 Inbox items finished and none late or overdue), KPI 90+ (KPI score so far 90 or more), Top 3 (first three of your division, when it has 4 or more people) and Learner (a course certificate this month). Press a badge or “How to earn them” to see each rule and where you stand now. A badge can go away again in the same month, for example after a late day. Badges start again every month.', 'इस महीने के बैज मैप पर रैंकिंग के नीचे हैं और ऊपर की पट्टी में गिने जाते हैं। ये सात हैं, सब चालू महीने के आपके असली रिकॉर्ड से बनते हैं: समय का पक्का (एक भी दिन देर नहीं, कम से कम 5 दिन उपस्थित), पूरी हाज़िरी (एक भी दिन अनुपस्थित नहीं, कम से कम 5 दिन उपस्थित), 7 दिन लगातार (लगातार 7 कार्य दिन समय पर), इनबॉक्स हीरो (कम से कम 3 इनबॉक्स आइटम पूरे और कोई देर से या बाकी नहीं), KPI 90+ (अब तक का KPI स्कोर 90 या ज़्यादा), टॉप 3 (अपने डिवीज़न के पहले तीन में, जब उसमें 4 या ज़्यादा लोग हों) और सीखने वाला (इस महीने एक कोर्स सर्टिफ़िकेट)। हर नियम और आप अभी कहाँ हैं, यह देखने के लिए बैज या “ये कैसे मिलते हैं” दबाएँ। बैज उसी महीने में वापस जा भी सकता है, जैसे एक दिन देर होने पर। बैज हर महीने नए सिरे से शुरू होते हैं।'],
      ['When you get a new badge, or your career level goes up, the map shows a short celebration once. Press anywhere to close it. It is shown once, on whichever phone or computer you open the map first. Badges have no effect on KPI score, salary or attendance.', 'नया बैज मिलने पर या करियर लेवल बढ़ने पर मैप एक बार छोटा सा जश्न दिखाता है। बंद करने के लिए कहीं भी दबाएँ। यह एक बार दिखता है, जिस फ़ोन या कंप्यूटर पर आप मैप पहले खोलें। बैज का KPI स्कोर, सैलरी या हाज़िरी पर कोई असर नहीं है।'],
      ['For Admin and HR: Reports > PMS > “Badges of the month (employee-wise)” lists every employee with each badge, by month. The running month is worked out when the report is opened. An earlier month shows what was saved: badges are saved once a day when Admin or HR opens Mirror-HR (up to 150 employees), and by the Scheduler job “Save the badges of the month for every employee”. A month in which nobody saved them shows no badges. A manager sees his own team.', 'Admin और HR के लिए: Reports > PMS > “Badges of the month (employee-wise)” में हर कर्मचारी के हर बैज की सूची है, महीने के हिसाब से। चालू महीना रिपोर्ट खोलते समय निकाला जाता है। पिछला महीना वही दिखाता है जो सेव हुआ था: बैज दिन में एक बार सेव होते हैं जब Admin या HR Mirror-HR खोलते हैं (150 कर्मचारियों तक), और शेड्यूलर के काम “हर कर्मचारी के इस महीने के बैज सेव करें” से। जिस महीने किसी ने सेव नहीं किए उसमें बैज नहीं दिखते। मैनेजर को अपनी टीम दिखती है।']] },
  { id: 'inbox', n: ['My tasks', 'मेरे काम'],
    path: ['Inbox > My tasks', 'Inbox > My tasks'],
    what: ['One list of your work. It is in three parts: what needs your decision, what you have to do, and what is only for your information. Each row says in one word what you must do and gives the right button.', 'आपके काम की एक लिस्ट। यह तीन हिस्सों में है: जिसमें आपका फ़ैसला चाहिए, जो आपको करना है, और जो सिर्फ़ जानकारी के लिए है। हर रो में एक शब्द में लिखा है कि आपको क्या करना है और सही बटन दिया है।'],
    why: ['So that nothing is missed and you never have to hunt through the modules to find what is waiting.', 'ताकि कुछ छूटे नहीं और आपको बाकी काम ढूँढने के लिए मॉड्यूल-मॉड्यूल घूमना न पड़े।'],
    who: ['Everyone. You see only what is with you. Others cannot see your items.', 'सब। आपको सिर्फ़ वही दिखता है जो आपके पास है। दूसरे आपके आइटम नहीं देख सकते।'],
    steps: [['Open Inbox. Start from the top: “Needs your decision” first, then “You have work to do”, then “For your information”.', 'Inbox खोलें। ऊपर से शुरू करें: पहले “आपका फ़ैसला चाहिए”, फिर “आपको काम करना है”, फिर “सिर्फ़ जानकारी के लिए”।'], ['For an approval, press Approve to approve at once, or “Details / Reject” to read it and give a remark. A remark is needed to reject.', 'मंज़ूरी के लिए Approve दबाकर तुरंत मंज़ूर करें, या पढ़ने और टिप्पणी देने के लिए “Details / Reject” दबाएँ। अस्वीकार करने के लिए टिप्पणी ज़रूरी है।'], ['For work, press the button on the row (for example “Open and verify”). It takes you to the screen where the work is done. The item leaves your Inbox by itself when the work is done.', 'काम के लिए रो का बटन दबाएँ (जैसे “Open and verify”)। यह आपको उस स्क्रीन पर ले जाता है जहाँ काम होता है। काम पूरा होते ही आइटम अपने आप Inbox से हट जाता है।'], ['For information, read it and press Read.', 'जानकारी के लिए पढ़ें और Read दबाएँ।'], ['To approve many at once, tick the approvals and press “Approve selected”.', 'कई मंज़ूरियाँ एक साथ करने के लिए उन पर टिक लगाएँ और “Approve selected” दबाएँ।']],
    notes: [['The three boxes on top show how many items are in each part. Press a box to show only that part.', 'ऊपर के तीन बॉक्स हर हिस्से की गिनती दिखाते हैं। केवल वही हिस्सा देखने के लिए बॉक्स दबाएँ।'], ['Under each row you can read who sent it and why it came to you, for example “WF-030, step 2: you are Division Manager”.', 'हर रो के नीचे पढ़ सकते हैं कि किसने भेजा और आपके पास क्यों आया, जैसे “WF-030, step 2: आप Division Manager हैं”।'], ['Late items come first.', 'देर वाले आइटम सबसे ऊपर आते हैं।'],
      ['Every item has a last date, shown in the Due column. An item that has its own last date keeps it (for example a training test or a trip report). Every other item gets the day it came plus working days: an approval or other work 2, an acknowledgement (letter, decision, document, asset, notice board) 3, a notice to read 2. Sundays and holidays are not counted. Admin and HR change these days in Core Setting > SLA master, SLA-053.', 'हर आइटम की एक आख़िरी तारीख़ होती है, जो Due कॉलम में दिखती है। जिस आइटम की अपनी आख़िरी तारीख़ है वह वही रखता है (जैसे ट्रेनिंग टेस्ट या यात्रा रिपोर्ट)। बाकी हर आइटम को आने का दिन और कार्य दिन मिलते हैं: मंज़ूरी या कोई और काम 2, पावती (पत्र, निर्णय, दस्तावेज़, एसेट, नोटिस बोर्ड) 3, पढ़ने की सूचना 2। रविवार और छुट्टियाँ नहीं गिनी जातीं। Admin और HR ये दिन Core Setting > SLA master, SLA-053 में बदलते हैं।'],
      ['The Due column shows “due tomorrow”, “due today” or “overdue” next to the date. Finish, acknowledge or read the item on or before the last date.', 'Due कॉलम में तारीख़ के साथ “कल आख़िरी दिन”, “आज आख़िरी दिन” या “समय निकल गया” दिखता है। आइटम को आख़िरी तारीख़ तक पूरा करें, पावती दें या पढ़ें।'],
      ['KPI-399 “Inbox Tasks Done Before Due %” is worked out by the system from this list: items finished on or before the last date ÷ items whose last date has come × 100. An item finished late, or still open after the last date, counts as late. To Do items and Today\'s Challenge are not counted here (they have their own KPI). It is counted for items due from 1 December 2026. HR assigns the KPI in PMS > KPI assignment, like every other KPI; it scores only for the people it is assigned to.', 'KPI-399 “Inbox Tasks Done Before Due %” सिस्टम इसी लिस्ट से निकालता है: आख़िरी तारीख़ तक पूरे हुए आइटम ÷ जिन आइटम की आख़िरी तारीख़ आ चुकी × 100। देर से पूरा हुआ या आख़िरी तारीख़ के बाद भी बाकी आइटम देर गिना जाता है। To Do और Today\'s Challenge यहाँ नहीं गिने जाते (उनकी अपनी KPI है)। यह 1 दिसंबर 2026 से देय आइटम के लिए गिनी जाती है। HR यह KPI बाकी KPI की तरह PMS > KPI assignment में असाइन करता है; स्कोर सिर्फ़ उन्हीं का बनता है जिन्हें यह असाइन है।'],
      ['An item of another module is noted as finished on the day you open Mirror-HR after finishing it. Reports > PMS has “Inbox TAT report (employee-wise)” and “Inbox items (item-wise, with last date)”, both by month.', 'दूसरे मॉड्यूल का आइटम उस दिन पूरा दर्ज होता है जिस दिन आप उसे पूरा करने के बाद Mirror-HR खोलते हैं। Reports > PMS में “Inbox TAT report (employee-wise)” और “Inbox items (item-wise, with last date)” हैं, दोनों महीने के हिसाब से।']] },
  { id: 'sent', n: ['Sent by me', 'मेरे भेजे'],
    path: ['Inbox > Sent by me', 'Inbox > Sent by me'],
    what: ['The approvals you started, and with whom each one is now.', 'आपके शुरू की हुई मंज़ूरियाँ और अभी हर एक किसके पास है।'],
    why: ['So that you can follow your request without asking anyone.', 'ताकि आप बिना किसी से पूछे अपनी माँग को ट्रैक कर सकें।'],
    who: ['Everyone who has started an approval.', 'जिसने भी कोई मंज़ूरी शुरू की हो।'],
    steps: [['Open Inbox > Sent by me.', 'Inbox > Sent by me खोलें।'], ['Read “Now with” to see who must act.', '“Now with” पढ़ें कि अब किसे करना है।'], ['Press Trail to see every step and remark.', 'हर स्टेप और टिप्पणी देखने के लिए Trail दबाएँ।']] },
  { id: 'wf', n: ['All approvals', 'सभी मंज़ूरियाँ'],
    path: ['Inbox > All approvals (HR and manager)', 'Inbox > All approvals (HR और मैनेजर)'],
    what: ['Every approval of the company with its flow, step and status.', 'कंपनी की हर मंज़ूरी, उसका वर्कफ़्लो, स्टेप और स्थिति।'],
    why: ['So that HR can see where an approval is stuck.', 'ताकि HR देख सके कि कोई मंज़ूरी कहाँ अटकी है।'],
    who: ['HR and managers.', 'HR और मैनेजर।'], hr: true,
    steps: [['Open Inbox > All approvals.', 'Inbox > All approvals खोलें।'], ['Find the approval and press Trail to see who has it now.', 'मंज़ूरी ढूँढें और अभी किसके पास है यह देखने के लिए Trail दबाएँ।']],
    notes: [['Which steps an approval has, and who approves each step, is set in Core Setting > Automation > Workflow.', 'किसी मंज़ूरी में कौन-से स्टेप हैं और हर स्टेप कौन मंज़ूर करता है, यह Core Setting > Automation > Workflow में तय होता है।']] },
  { id: 'sched', n: ['Scheduler', 'शेड्यूलर'],
    path: ['Inbox > Scheduler (HR and manager)', 'Inbox > Scheduler (HR और मैनेजर)'],
    what: ['The reminders and escalations that run on a timer, for example expiring advance requests or closing training tests. You can run each one by hand here.', 'वे रिमाइंडर और एस्केलेशन जो टाइमर पर चलते हैं, जैसे एडवांस की माँग का खत्म होना या ट्रेनिंग टेस्ट बंद करना। यहाँ से हर एक को हाथ से भी चला सकते हैं।'],
    why: ['So that overdue things do not wait for someone to remember.', 'ताकि देर वाले काम किसी के याद करने का इंतज़ार न करें।'],
    who: ['HR and managers.', 'HR और मैनेजर।'], hr: true,
    steps: [['Open Inbox > Scheduler.', 'Inbox > Scheduler खोलें।'], ['Press Run next to a job, or Run all.', 'किसी जॉब के आगे Run दबाएँ, या Run all।']] }
]);

G('employees', ['Employees', 'कर्मचारी'], ['The list of everyone who works in the company and the form to add or change a person.', 'कंपनी में काम करने वाले सबकी लिस्ट और किसी को जोड़ने या बदलने का फ़ॉर्म।'], [
  { id: 'list', n: ['Employee list', 'कर्मचारी सूची'],
    path: ['Employees', 'Employees'],
    what: ['All employees with function, department, branch, division, sub-division, designation, career level and status. A blank career level means it is not set yet. You can search by name, code or mobile, and filter by branch and department.', 'सभी कर्मचारी, उनके फ़ंक्शन, डिपार्टमेंट, ब्रांच, डिवीज़न, सब-डिवीज़न, पद, करियर लेवल और स्थिति के साथ। ख़ाली करियर लेवल का मतलब है अभी तय नहीं हुआ। नाम, कोड या मोबाइल से खोज और ब्रांच-डिपार्टमेंट से फ़िल्टर कर सकते हैं।'],
    why: ['It is the master record of people. Payroll, attendance, KPI and every other module read from it.', 'यह लोगों का मास्टर रिकॉर्ड है। पेरोल, हाज़िरी, KPI और हर दूसरा मॉड्यूल इसी से पढ़ता है।'],
    who: ['HR and Admin. A manager sees his own team.', 'HR और Admin। मैनेजर अपनी टीम देखता है।'],
    steps: [['Open Employees.', 'Employees खोलें।'], ['Type a name, code or mobile in the search box.', 'सर्च बॉक्स में नाम, कोड या मोबाइल लिखें।'], ['Press View to read the full record. Press Cockpit to see the full picture of that person.', 'पूरा रिकॉर्ड पढ़ने के लिए View दबाएँ। उस व्यक्ति की पूरी तस्वीर के लिए Cockpit दबाएँ।'], ['Press Export CSV to download the list.', 'लिस्ट डाउनलोड करने के लिए Export CSV दबाएँ।']] },
  { id: 'add', n: ['Add or edit an employee', 'कर्मचारी जोड़ें या बदलें'],
    path: ['Employees > + Add employee', 'Employees > + Add employee'], hr: true,
    what: ['The form for a new employee or for changes. The job section follows the Organization structure in one order: Function, Department, Branch, Division, Sub-division, Designation. Each list shows only what is valid under the choice above it.', 'नए कर्मचारी या बदलाव का फ़ॉर्म। जॉब वाला हिस्सा Organization structure के एक क्रम में चलता है: Function, Department, Branch, Division, Sub-division, Designation। हर लिस्ट में सिर्फ़ वही दिखता है जो ऊपर वाले चुनाव के नीचे सही हो।'],
    why: ['So that a person can only be placed in a position that exists in the company structure.', 'ताकि कोई व्यक्ति सिर्फ़ उसी पद पर रखा जा सके जो कंपनी के स्ट्रक्चर में मौजूद है।'],
    who: ['HR and Admin.', 'HR और Admin।'],
    steps: [['Open Employees and press + Add employee.', 'Employees खोलें और + Add employee दबाएँ।'], ['Fill name, mobile, email, date of birth, gender and the highest education (chosen from a list: Below 10th, 10th pass, 12th pass, ITI, Diploma, Graduate, Post graduate (PG), Doctorate (PhD), Professional (CA, CS, CMA, LLB...) or Other; the course or stream is optional), then the date of joining. The education is shown in My Profile > Personal.', 'नाम, मोबाइल, ईमेल, जन्मतिथि, लिंग और सर्वोच्च शिक्षा (लिस्ट से चुनें: 10वीं से कम, 10वीं पास, 12वीं पास, ITI, डिप्लोमा, ग्रेजुएट, पोस्ट ग्रेजुएट (PG), डॉक्टरेट (PhD), प्रोफ़ेशनल (CA, CS, CMA, LLB...) या अन्य; कोर्स या स्ट्रीम वैकल्पिक है) भरें, फिर जॉइनिंग की तारीख़। शिक्षा My Profile > Personal में दिखती है।'], ['Choose Function, then Department, Branch, Division, Sub-division and Designation, in that order.', 'Function चुनें, फिर Department, Branch, Division, Sub-division और Designation, इसी क्रम में।'], ['Choose the reporting manager and the functional manager. The career level is left blank: HR sets it later, when setting the salary structure.', 'रिपोर्टिंग मैनेजर और फ़ंक्शनल मैनेजर चुनें। करियर लेवल ख़ाली रहता है: इसे HR बाद में, सैलरी स्ट्रक्चर तय करते समय भरता है।'], ['Fill statutory and bank details if known, then Save.', 'पता हों तो वैधानिक और बैंक विवरण भरें, फिर Save दबाएँ।']],
    notes: [['If a Designation is missing in the list, it must first be added in the Organization structure. See Workforce > Organization structure.', 'अगर लिस्ट में कोई Designation नहीं है तो उसे पहले Organization structure में जोड़ना होगा। देखें Workforce > Organization structure।'],
      ['The career level is not asked when a person is added, whether by this form or by the bulk upload: as soon as an employee has no salary structure for the career level, a task to set it goes to HR and Admin\'s Inbox (Payroll > Salary structure). The level can still be set directly on this form at any time.', 'करियर लेवल किसी व्यक्ति को जोड़ते समय नहीं पूछा जाता, चाहे इस फ़ॉर्म से हो या बल्क अपलोड से: जैसे ही किसी कर्मचारी का करियर लेवल के हिसाब से सैलरी स्ट्रक्चर नहीं है, HR और Admin के Inbox में उसे तय करने का टास्क आता है (Payroll > Salary structure)। लेवल इस फ़ॉर्म से कभी भी सीधे तय किया जा सकता है।'],
      ['Two more Inbox tasks keep step with it for a new employee, by bulk upload, + Add employee or recruitment alike: "Set the statutory assignment" (Payroll > Statutory assignment) as soon as PF, ESIC, PT, TDS and LWF are not yet set, and "Complete onboarding" for whichever of the other onboarding steps (KYC, KPI, reporting manager, shift, appointment letter) are still open, pointing to Workforce > Onboarding. Salary and statutory each have their own task and are not repeated in this one.', 'एक नए कर्मचारी के लिए दो और इनबॉक्स टास्क साथ चलते हैं, चाहे बल्क अपलोड से आया हो, + Add employee से या भर्ती से: "Set the statutory assignment" (Payroll > Statutory assignment) जैसे ही PF, ESIC, PT, TDS और LWF तय नहीं हैं, और "Complete onboarding" बाकी ऑनबोर्डिंग स्टेप के लिए (KYC, KPI, रिपोर्टिंग मैनेजर, शिफ़्ट, अपॉइंटमेंट लेटर) जो भी बाकी हों, Workforce > Onboarding की ओर इशारा करते हुए। सैलरी और स्टेट्यूटरी के अपने टास्क हैं, इसमें दोबारा नहीं आते।']] },
  { id: 'bulkmgr', n: ['Bulk change of manager', 'मैनेजर एक साथ बदलें'],
    path: ['Employees > Bulk change manager', 'Employees > Bulk change manager'], hr: true,
    what: ['Changes the reporting manager, the functional manager or both for many employees in one request. It goes through the approval workflow WF-030 (HR starts it, the Division Manager approves).', 'कई कर्मचारियों का रिपोर्टिंग मैनेजर, फ़ंक्शनल मैनेजर या दोनों एक ही माँग में बदलता है। यह अप्रूवल वर्कफ़्लो WF-030 से जाता है (HR शुरू करता है, Division Manager मंज़ूर करता है)।'],
    why: ['When a manager leaves or a team is reorganised, changing people one by one is slow and error-prone.', 'जब कोई मैनेजर जाता है या टीम बदली जाती है तो एक-एक करके बदलना धीमा है और उसमें गलती होती है।'],
    who: ['HR starts it. The Division Manager approves.', 'HR शुरू करता है। Division Manager मंज़ूर करता है।'],
    steps: [['Open Employees and press Bulk change manager.', 'Employees खोलें और Bulk change manager दबाएँ।'], ['Choose a group (function, department, branch, division, designation or current manager), or paste employee codes like E004, E005.', 'ग्रुप चुनें (function, department, branch, division, designation या मौजूदा मैनेजर), या E004, E005 जैसे कर्मचारी कोड पेस्ट करें।'], ['Untick anyone who should not change.', 'जिसे नहीं बदलना उसका टिक हटाएँ।'], ['Tick what to change and choose the new manager. Write the reason.', 'क्या बदलना है उस पर टिक लगाएँ और नया मैनेजर चुनें। कारण लिखें।'], ['Press Send for approval.', 'Send for approval दबाएँ।']],
    notes: [['When it is approved, the pending work the earlier manager holds for these employees moves to the new manager.', 'मंज़ूर होने पर पहले मैनेजर के पास इन कर्मचारियों का जो काम लंबित है वह नए मैनेजर को चला जाता है।'], ['A person cannot become his own manager, and two people cannot be managers of each other.', 'कोई अपना ही मैनेजर नहीं बन सकता, और दो लोग एक-दूसरे के मैनेजर नहीं बन सकते।']] }
]);

G('workforce', ['Workforce', 'वर्कफ़ोर्स'], ['The structure of the company and how people join, stay and leave.', 'कंपनी का स्ट्रक्चर और लोग कैसे जुड़ते, टिकते और जाते हैं।'], [
  { id: 'org', n: ['Organization structure', 'ऑर्गनाइज़ेशन स्ट्रक्चर'],
    path: ['Workforce > Organization structure', 'Workforce > Organization structure'],
    what: ['A chart of the whole company from top to bottom: Company, Function, Department, Branch, Division, Sub-division and Designation. Each designation shows how many are planned and how many are working.', 'पूरी कंपनी का ऊपर से नीचे चार्ट: Company, Function, Department, Branch, Division, Sub-division और Designation। हर पद के साथ कितने प्लान में हैं और कितने काम कर रहे हैं दिखता है।'],
    why: ['It is the base of everything. A designation can enter the Manpower plan, then a Requisition, then Recruitment, only if it exists here. Nobody can create a designation in the plan or in recruitment.', 'यह सबका आधार है। कोई पद तभी Manpower plan, फिर Requisition और फिर Recruitment में आ सकता है जब वह यहाँ हो। प्लान या भर्ती में कोई पद बनाया नहीं जा सकता।'],
    who: ['Everyone can read it. Admin and HR with the right to add can build it. We build it for each client when the ERP is given.', 'पढ़ सब सकते हैं। जोड़ने का अधिकार वाले Admin और HR इसे बना सकते हैं। क्लाइंट को ERP देते समय हम इसे बनाते हैं।'],
    steps: [['Open Workforce > Organization structure.', 'Workforce > Organization structure खोलें।'], ['To add something, press the small + button under a box: under Company add a Function, under a Function add a Department, under a Department add a Branch, under a Branch add a Division, under a Division add a Sub-division, under a Sub-division add a Designation.', 'कुछ जोड़ने के लिए बॉक्स के नीचे का छोटा + बटन दबाएँ: Company के नीचे Function, Function के नीचे Department, Department के नीचे Branch, Branch के नीचे Division, Division के नीचे Sub-division, Sub-division के नीचे Designation।'], ['The form opens with the parent already chosen. Write the name and Save. A designation has no level: the career level is chosen for each person when making the offer in Recruitment and when giving a salary structure.', 'फ़ॉर्म में parent पहले से चुना होता है। नाम लिखें और Save दबाएँ। पद का कोई लेवल नहीं होता: करियर लेवल हर व्यक्ति के लिए Recruitment में ऑफ़र देते समय और सैलरी स्ट्रक्चर देते समय चुना जाता है।'], ['To edit or inactivate something, press Edit structure in Settings.', 'कुछ बदलने या inactivate करने के लिए Edit structure in Settings दबाएँ।']],
    notes: [['A function, department, branch, division, sub-division or designation that is used in the manpower plan, in a requisition that waits or in an open vacancy cannot be inactivated. The screen shows where it is used.', 'जो function, department, branch, division, sub-division या पद manpower plan, इंतज़ार वाली requisition या खुली vacancy में चल रहा है उसे inactivate नहीं कर सकते। स्क्रीन दिखाती है कि वह कहाँ इस्तेमाल हो रहा है।'], ['A designation is mapped under Divisions, not under one Sub-division: in Core Setting > Designations tick the Divisions where the post exists (it then works in all their sub-divisions). Only if it is needed in some sub-divisions alone, tick those small boxes under the Division. One designation can be ticked under many Divisions. A new Division is added to the shared sub-division called General automatically.', 'पद Divisions के नीचे जुड़ता है, किसी एक Sub-division के नीचे नहीं: Core Setting > Designations में उन Divisions को टिक करें जहाँ यह पद है (तब यह उनकी सभी Sub-division में चलता है)। सिर्फ़ कुछ Sub-division में चाहिए तो Division के नीचे के छोटे बॉक्स टिक करें। एक पद कई Divisions में टिक हो सकता है। नई Division अपने-आप General नाम की साझा Sub-division में जुड़ जाती है।'], ['A new Branch is created from Core Setting > Branches, because the chart shows one company at a time.', 'नई Branch Core Setting > Branches से बनती है।']] },
  { id: 'attr', n: ['Attrition and retention', 'एट्रिशन और रिटेंशन'],
    path: ['Workforce > Attrition and retention', 'Workforce > Attrition and retention'],
    what: ['For a period you choose: headcount at the start and the end, joiners, exits, the attrition percentage and the retention percentage. The same table is shown by branch, by division and by designation. At the bottom is a list of employees who may leave, with risk points and the reasons.', 'आपके चुने हुए समय के लिए: शुरू और अंत की संख्या, जॉइन करने वाले, छोड़ने वाले, एट्रिशन प्रतिशत और रिटेंशन प्रतिशत। यही टेबल ब्रांच, डिवीज़न और पद के हिसाब से भी दिखती है। सबसे नीचे उन कर्मचारियों की लिस्ट है जो छोड़ सकते हैं, रिस्क पॉइंट और कारण के साथ।'],
    why: ['So that HR can see problems in time, by branch, division or designation, and talk to the people at risk before they leave.', 'ताकि HR समस्या समय पर देख सके, ब्रांच, डिवीज़न या पद के हिसाब से, और जाने से पहले जोखिम वाले लोगों से बात कर सके।'],
    who: ['HR, Admin.', 'HR, Admin।'], hr: true,
    steps: [['Open Workforce > Attrition and retention.', 'Workforce > Attrition and retention खोलें।'], ['Choose the period at the top (last 12 months, financial year or one month).', 'ऊपर से समय चुनें (पिछले 12 महीने, वित्त वर्ष या एक महीना)।'], ['Read the four boxes. Press a box (for example Exits) to see the names.', 'चार बॉक्स पढ़ें। नाम देखने के लिए किसी बॉक्स (जैसे Exits) को दबाएँ।'], ['Read the tables by branch, division and designation. Press a number to see who it is.', 'ब्रांच, डिवीज़न और पद की टेबल पढ़ें। कौन हैं यह देखने के लिए संख्या दबाएँ।'], ['Read the risk list at the bottom and plan a talk with the high-risk people.', 'नीचे की रिस्क लिस्ट पढ़ें और ज़्यादा जोखिम वाले लोगों से बात की योजना बनाएँ।']] },
  { id: 'join', n: ['Joining to retention', 'जॉइनिंग से रिटेंशन'],
    path: ['Workforce > Joining to retention', 'Workforce > Joining to retention'],
    what: ['One row for each month in which people joined (last 12 months): how many joined, how many stayed beyond the retention window, how many left inside it, how many are still inside it, and the retention percentage.', 'हर उस महीने की एक रो जिसमें लोग जुड़े (पिछले 12 महीने): कितने जुड़े, कितने रिटेंशन विंडो के बाद भी रुके, कितने उसके अंदर छोड़ गए, कितने अभी उसके अंदर हैं, और रिटेंशन प्रतिशत।'],
    why: ['To see if the hiring and the first days of the new people are working.', 'ताकि पता चले कि भर्ती और नए लोगों के शुरू के दिन ठीक चल रहे हैं या नहीं।'],
    who: ['HR, Admin.', 'HR, Admin।'], hr: true,
    steps: [['Open Workforce > Joining to retention.', 'Workforce > Joining to retention खोलें।'], ['Read the row of a month: joiners, retained, left, still in the window.', 'किसी महीने की रो पढ़ें: जुड़े, रुके, गए, अभी विंडो में।'], ['The retention percentage appears when no one of that month is still inside the window.', 'रिटेंशन प्रतिशत तब दिखता है जब उस महीने का कोई भी व्यक्ति विंडो के अंदर न बचा हो।']],
    notes: [['The length of the retention window (in days) is a number in Core Setting > Rules and numbering > SLA.', 'रिटेंशन विंडो की लंबाई (दिनों में) Core Setting > Rules and numbering > SLA की एक संख्या है।']] },
  { id: 'uniform', n: ['Uniform and ID card', 'यूनिफ़ॉर्म और ID कार्ड'],
    path: ['Workforce > Uniform & ID card', 'Workforce > Uniform & ID card'],
    what: ['A register of who has been given a uniform and an ID card, and on what date.', 'किसे यूनिफ़ॉर्म और ID कार्ड कब दिया गया उसका रजिस्टर।'],
    why: ['So that new joiners are not forgotten and the date of handover is on record.', 'ताकि नए जॉइन करने वाले छूटें नहीं और देने की तारीख़ रिकॉर्ड में रहे।'],
    who: ['HR.', 'HR।'], hr: true,
    steps: [['Open Workforce > Uniform & ID card.', 'Workforce > Uniform & ID card खोलें।'], ['Find the employee and enter the date the uniform or ID card was given.', 'कर्मचारी ढूँढें और यूनिफ़ॉर्म या ID कार्ड देने की तारीख़ भरें।']] },
  { id: 'onb', n: ['Onboarding and KYC', 'ऑनबोर्डिंग और KYC'],
    path: ['Workforce > Onboarding & KYC', 'Workforce > Onboarding & KYC'],
    what: ['The documents of each new employee (identity, address, bank) and their check. A document the employee uploads is verified by HR.', 'हर नए कर्मचारी के दस्तावेज़ (पहचान, पता, बैंक) और उनकी जाँच। कर्मचारी का अपलोड किया दस्तावेज़ HR सत्यापित करता है।'],
    why: ['So that the records are complete and checked before the first salary.', 'ताकि पहली सैलरी से पहले रिकॉर्ड पूरे और जाँचे हुए हों।'],
    who: ['The employee uploads. HR verifies.', 'कर्मचारी अपलोड करता है। HR सत्यापित करता है।'],
    steps: [['The employee opens his own onboarding and uploads each document.', 'कर्मचारी अपना ऑनबोर्डिंग खोलकर हर दस्तावेज़ अपलोड करता है।'], ['HR opens Workforce > Onboarding & KYC, reads the document and marks it verified.', 'HR Workforce > Onboarding & KYC खोलकर दस्तावेज़ पढ़ता है और verified करता है।']],
    notes: [['A document waiting for verification appears in the Inbox of HR as “Verify KYC documents”.', 'जाँच के इंतज़ार वाला दस्तावेज़ HR के Inbox में “Verify KYC documents” के रूप में आता है।']] }
]);
